INSERT INTO chart_of_accounts (company_id, code, name, account_type, is_active, is_header, is_postable, account_category)
SELECT co.id, t.code, t.name, t.account_type, true, t.is_header, NOT t.is_header, t.account_category
FROM companies co
CROSS JOIN tmp_local_coa_import t
WHERE co.name IN ('Nishtimani Yakam', 'Nishtimani Factory', 'Al Watanyia');

UPDATE chart_of_accounts c SET parent_id = p.id
FROM chart_of_accounts p, tmp_local_coa_import t
WHERE t.code = c.code AND p.code = t.parent_code AND c.company_id = p.company_id
  AND c.is_active = true AND p.is_active = true;

UPDATE chart_of_accounts c SET group_account_id = g.id
FROM group_chart_of_accounts g
WHERE c.code = g.code AND c.is_active = true AND g.is_active = true;

DROP TABLE tmp_local_coa_import;
